drop table if exists mob_drops;
create table mob_drops (
    id bigint not null auto_increment,
    mobid int,
    itemid int,
    chance int,
    minquant int default 1,
    maxquant int default 1,
    reactordrop bit default 0,
    primary key (id)
);

